// ==========================================================================
// Мониторинг
// ==========================================================================

const ALERT_STATE_LABEL = { ok: 'норма', pending: 'наблюдение', firing: 'тревога' };
const ALERT_STATE_CLASS = { ok: 'ok', pending: 'warn', firing: 'err' };
const TARGET_KIND_LABEL = {
  prometheus_pushgateway: 'Prometheus Pushgateway',
  influxdb: 'InfluxDB',
  otlp: 'OpenTelemetry (OTLP)',
  statsd: 'StatsD / Graphite',
  webhook: 'Webhook (JSON)',
  zabbix: 'Zabbix (траппер)',
};

/* Подсказка к адресу приёмника: у каждого вида свой. */
const TARGET_URL_HINT = {
  prometheus_pushgateway: 'http://pushgw:9091',
  influxdb: 'http://influx:8086',
  otlp: 'http://otel-collector:4318',
  statsd: 'udp://statsd:8125',
  webhook: 'https://ваш-сервис/metrics',
  zabbix: 'zabbix://zabbix-server:10051',
};

RENDERERS.monitoring = {
  async render(root) {
    root.innerHTML = '<div class="empty">Опрос метрик…</div>';
    let health;
    let info;
    let alerts;
    let targets;
    // Ошибку пробрасываем: её покажет renderView карточкой с кнопкой
    // «Повторить», а не оставит раздел на «Опрос метрик…» насовсем.
    [health, info, alerts, targets] = await Promise.all([
      // Состояние — снисходительным запросом: 503 здесь означает «плохо со
      // здоровьем», а не «нет ответа», и тело при этом полное.
      API.lenient('/api/monitoring/health'),
      API.get('/api/monitoring/info'),
      API.lenient('/api/monitoring/alerts'),
      API.lenient('/api/monitoring/targets'),
    ]);

    state.monitoring = { health, info, alerts, targets };
    const summary = alerts.summary || {};
    // Цвет и слово — об одном и том же. Сервер называет состояние
    // «внимание», когда горит любая тревога, а цвет брался от самой тяжёлой
    // тревоги: выходила красная плашка «внимание». Горит критическая —
    // так и пишем.
    const состояние = health.status === 'warning' && summary.worst === 'critical'
      ? 'critical_alert' : health.status;
    const worstClass = { ok: 'ok', warning: 'warn' }[состояние] || 'err';

    root.innerHTML = `
      <div class="grid cols-4" style="margin-bottom:16px">
        ${kpi('Состояние', `<span class="chip ${worstClass}">${
          esc(healthLabel(состояние))}</span>`, `работает ${fmtDur(health.uptime_s)}`)}
        ${kpi('Тревог сейчас', summary.firing || 0,
              `${summary.critical || 0} критических, ${summary.warning || 0} предупреждений`)}
        ${kpi('Метрик в снимке', info.samples || 0, `правил: ${summary.rules || 0}`)}
        ${kpi('Опросов', info.scrapes || 0, `кеш ${info.cache_ttl_s} с`)}
      </div>

      ${(info.collection_errors || []).length ? `<section class="card" style="border-color:var(--warn)">
        <div class="card-head"><h3 style="color:var(--warn)">Источники, которые не опрашиваются</h3>
          <span class="hint">остальные метрики собираются как обычно</span></div>
        <ul style="margin:0;padding-left:18px" class="small">
          ${info.collection_errors.map((e) => `<li>${esc(e)}</li>`).join('')}</ul></section>` : ''}

      ${card('Нагрузка сервера', 'ряды за выбранное окно — таблица показывает текущее значение, а нужен ход',
             `<div class="settings-toolbar" style="position:static;padding:0 0 10px">
                <span class="small dim">Окно:</span>
                <div class="group-nav" id="mon-window">
                  ${[[15, '15 мин'], [60, 'час'], [360, '6 часов'], [1440, 'сутки'],
                     [10080, 'неделя']].map(([m, л]) =>
                    `<button data-minutes="${m}"${m === 60 ? ' class="active"' : ''}>${л}</button>`).join('')}
                </div>
                <span class="spacer"></span>
                <span class="small faint" id="mon-sampled"></span>
              </div>
              <div id="mon-charts"><div class="empty">Загрузка рядов…</div></div>`)}

      ${card('Пробы состояния',
             'liveness — перезапустить контейнер; readiness — снять нагрузку',
             `<div class="grid cols-3">${
               ['liveness', 'readiness', 'startup'].map((probe) => probeCard(probe, health[probe])).join('')
             }</div>`)}

      ${card('Тревоги', 'пороги берутся из каталога метрик и правятся ниже, в «Правилах тревог»',
             alertsTable(alerts.alerts || []),
             `<button class="ghost admin-only" id="mon-reset-rules">Вернуть пороги по умолчанию</button>`)}

      ${card('Правила тревог', 'порог, важность и выдержка каждого правила; сохраняются в файл конфигурации',
             `<details id="mon-rules-box"><summary class="small">Показать и править правила (${
               num(summary.rules || 0)})</summary>
               <div id="mon-rules" style="margin-top:8px"><div class="empty small">Загрузка…</div></div>
             </details>`)}

      ${card('История срабатываний', 'смены состояния тревог с запуска сервера, новые сверху',
             '<div id="mon-history"><div class="empty small">Загрузка…</div></div>')}

      ${card('Куда отправляются метрики',
             'нужно там, где до сервера не достучаться снаружи',
             targetsTable(targets),
             `<button class="ghost admin-only" id="mon-add-target">Добавить приёмник</button>`)}

      ${card('Как забрать метрики', 'адреса относительно этого сервера',
             endpointsTable())}

      ${card('Готовые настройки для систем мониторинга',
             'собираются из каталога метрик, поэтому не расходятся с ним',
             `<div class="row" style="gap:8px;flex-wrap:wrap">
                <button class="ghost" data-mon-file="/api/monitoring/config/prometheus"
                  data-name="asrhub-rules.yml">Правила Prometheus</button>
                <button class="ghost" data-mon-file="/api/monitoring/config/prometheus-scrape"
                  data-name="asrhub-scrape.yml">Задание для scrape_configs</button>
                <button class="ghost" data-mon-file="/api/monitoring/config/grafana"
                  data-name="asrhub-grafana.json">Панель Grafana</button>
                <button class="ghost" data-mon-file="/api/monitoring/config/zabbix"
                  data-name="asrhub-zabbix.yaml">Шаблон Zabbix</button>
              </div>
              <p class="small dim" style="margin-top:10px">Пороги в этих файлах — отправная
              точка. Подгоняйте под свой поток: очередь из ста заданий бывает и нормой,
              и аварией.</p>`)}

      ${card('Справочник метрик', `${info.samples || 0} значений в снимке`,
             `<div class="settings-toolbar" style="position:static;padding:0 0 10px">
                <input type="search" id="mon-search" placeholder="поиск по метрикам"
                       style="width:280px">
                <span class="spacer"></span>
                <span class="small faint" id="mon-count"></span>
              </div>
              <div id="mon-catalog"><div class="empty">Загрузка справочника…</div></div>`)}
    `;

    qs('#mon-reset-rules').onclick = async () => {
      // Сброс заменяет все правила, в том числе свои, — после подтверждения:
      // раньше он выполнялся одним щелчком, с записью в конфигурацию.
      if (!confirm(`Вернуть пороги тревог к значениям каталога?\n\nВсе правила (${
        num(summary.rules || 0)}) заменятся правилами каталога метрик; свои пороги `
        + 'и выключенные правила пропадут, в том числе из файла конфигурации.')) return;
      try {
        const итог = await API.post('/api/monitoring/alerts/rules/reset');
        toast('Пороги возвращены к значениям каталога',
              итог.persisted === false ? 'warn' : 'ok', persistedHint(итог));
        renderView();
      } catch (err) { fail(err); }
    };
    qs('#mon-add-target').onclick = () => targetDialog();
    // Правила грузятся, когда их раскрыли: их шесть десятков, а смотрят
    // их изредка. История — сразу: она короткая и нужна при каждой тревоге.
    const правила = qs('#mon-rules-box');
    if (правила) правила.addEventListener('toggle', () => {
      if (правила.open) this.loadRules(alerts);
    });
    this.loadHistory();
    // Готовые настройки и адреса сбора — с ключом в заголовке: обычная
    // ссылка при закрытых метриках отвечала 401 вошедшему по ключу.
    qsa('[data-mon-file]').forEach((кнопка) => {
      кнопка.onclick = async () => {
        кнопка.disabled = true;
        try {
          await скачатьФайл(кнопка.dataset.monFile, кнопка.dataset.name);
        } catch (err) { fail(err); } finally { кнопка.disabled = false; }
      };
    });
    qsa('[data-mon-open]').forEach((ссылка) => {
      ссылка.onclick = (е) => { е.preventDefault(); открытьВкладкой(ссылка.dataset.monOpen); };
    });
    qsa('[data-drop-target]').forEach((кнопка) => {
      кнопка.onclick = async () => {
        const имя = кнопка.dataset.dropTarget;
        if (!confirm(`Убрать приёмник «${имя}»? Метрики туда больше не пойдут.`)) return;
        try {
          const итог = await API.del(`/api/monitoring/targets/${encodeURIComponent(имя)}`);
          toast(`Приёмник «${имя}» убран`, итог.persisted === false ? 'warn' : 'ok',
                persistedHint(итог));
          renderView();
        } catch (err) { fail(err); }
      };
    });
    // Включить и выключить приёмник — списком целиком (PUT): описание из
    // ответа GET несёт все поля, а заголовки — заглушками, которые сервер
    // читает как «оставить как было».
    qsa('[data-toggle-target]').forEach((кнопка) => {
      кнопка.onclick = (е) => занятьКнопку(е.currentTarget, async () => {
        const список = (targets.targets || []).map((t) => {
          const { name, kind, url, interval_s: интервал, enabled, job, instance, prefix,
                  database, timeout_s: тайм, host, headers } = t;
          return { name, kind, url, interval_s: интервал, enabled, job, instance, prefix,
                   database, timeout_s: тайм, host, headers };
        });
        const цель = список.find((t) => t.name === кнопка.dataset.toggleTarget);
        if (!цель) return;
        цель.enabled = цель.enabled === false;
        try {
          const итог = await API.put('/api/monitoring/targets', список);
          toast(`Приёмник «${цель.name}» ${цель.enabled ? 'включён' : 'выключен'}`,
                persistedKind(итог), persistedHint(итог));
          renderView();
        } catch (err) { fail(err); }
      });
    });
    qsa('#mon-window button').forEach((b) => b.addEventListener('click', () => {
      qsa('#mon-window button').forEach((x) => x.classList.toggle('active', x === b));
      this.loadResources(Number(b.dataset.minutes));
    }));
    this.loadResources(60);
    this.loadCatalog();
  },

  /* Правила тревог — GET и PUT /api/monitoring/alerts/rules.
   *
   * Интерфейс умел только «Вернуть пороги по умолчанию», хотя документация
   * обещала правку «в разделе». Список уходит целиком — тем же, что пришёл,
   * с правками порога, важности, выдержки и включения: так ни одно из
   * правил каталога не теряется (PUT заменяет набор полностью). */
  async loadRules(тревоги) {
    const место = qs('#mon-rules');
    if (!место) return;
    let д;
    try { д = await API.get('/api/monitoring/alerts/rules'); } catch (err) {
      if (err && err.silent) return;
      место.innerHTML = `<div class="empty small">${esc(err.message || 'правила недоступны')}</div>`;
      return;
    }
    const правила = д.rules || [];
    const имена = {};
    ((тревоги || {}).alerts || []).forEach((а) => { имена[а.metric] = а.label; });
    const админ = (state.me || {}).role === 'admin';
    место.innerHTML = `<div class="table-wrap"><table class="small">
      <thead><tr><th>Вкл.</th><th>Метрика</th><th>Условие</th><th>Порог</th>
        <th>Важность</th><th>Выдержка, с</th></tr></thead>
      <tbody>${правила.map((п, i) => `<tr data-rule="${i}">
        <td><input type="checkbox" data-f="enabled" ${п.enabled !== false ? 'checked' : ''}
          style="width:auto" ${админ ? '' : 'disabled'}></td>
        <td><b>${esc(имена[п.metric] || п.metric)}</b><div class="faint mono">${esc(п.metric)}${
          Object.keys(п.labels || {}).length ? ` · ${esc(Object.entries(п.labels)
            .map(([к, з]) => `${к}=${з}`).join(', '))}` : ''}</div></td>
        <td class="mono">${знакПорога(п.direction, п.inclusive)}</td>
        <td><input type="number" data-f="threshold" step="any" value="${esc(String(п.threshold))}"
          style="width:110px" ${админ ? '' : 'disabled'}></td>
        <td><select data-f="severity" style="width:130px" ${админ ? '' : 'disabled'}>
          <option value="warning"${п.severity === 'warning' ? ' selected' : ''}>предупреждение</option>
          <option value="critical"${п.severity === 'critical' ? ' selected' : ''}>критично</option></select></td>
        <td><input type="number" data-f="for_seconds" min="0" step="10" value="${esc(String(п.for_seconds || 0))}"
          style="width:90px" ${админ ? '' : 'disabled'}></td></tr>`).join('')}</tbody></table></div>
      ${админ ? `<div class="row" style="gap:8px;margin-top:10px">
        <button class="primary sm" id="mon-rules-save" disabled>Сохранить правила</button>
        <span class="small dim" id="mon-rules-state"></span></div>` : ''}`;
    const сохранить = qs('#mon-rules-save', место);
    if (!сохранить) return;
    qsa('[data-f]', место).forEach((поле) => поле.addEventListener('change', () => {
      сохранить.disabled = false;
      qs('#mon-rules-state', место).textContent = 'есть несохранённые правки';
    }));
    сохранить.onclick = (е) => занятьКнопку(е.currentTarget, async () => {
      const набор = правила.map((п, i) => {
        const строка = qs(`tr[data-rule="${i}"]`, место);
        const порог = Number(qs('[data-f="threshold"]', строка).value);
        const { id, ...правило } = п;            // имя правила сервер выводит сам
        void id;
        return Object.assign(правило, {
          enabled: qs('[data-f="enabled"]', строка).checked,
          threshold: Number.isFinite(порог) ? порог : п.threshold,
          severity: qs('[data-f="severity"]', строка).value,
          for_seconds: Math.max(0, Math.round(Number(qs('[data-f="for_seconds"]', строка).value) || 0)),
        });
      });
      try {
        const итог = await API.put('/api/monitoring/alerts/rules', набор);
        toast(`Правила сохранены: ${num(итог.rules || набор.length)}`, persistedKind(итог),
              persistedHint(итог));
        qs('#mon-rules-state', место).textContent = '';
      } catch (err) { fail(err); }
    });
  },

  /* История срабатываний — GET /api/monitoring/alerts/history. */
  async loadHistory() {
    const место = qs('#mon-history');
    if (!место) return;
    let д;
    try { д = await API.get('/api/monitoring/alerts/history?limit=50'); } catch (err) {
      if (err && err.silent) return;
      место.innerHTML = `<div class="empty small">${esc(err.message || 'история недоступна')}</div>`;
      return;
    }
    const записи = д.items || [];
    место.innerHTML = записи.length ? `<div class="table-wrap"><table class="small">
      <thead><tr><th>Когда</th><th>Было → стало</th><th>Метрика</th><th>Значение</th><th>Порог</th></tr></thead>
      <tbody>${записи.map((з) => `<tr>
        <td class="nowrap faint">${esc(fmtTime(з.ts))}</td>
        <td><span class="chip ${ALERT_STATE_CLASS[з.from] || ''}">${esc(ALERT_STATE_LABEL[з.from] || з.from || '—')}</span>
          → <span class="chip ${ALERT_STATE_CLASS[з.state] || ''}">${esc(ALERT_STATE_LABEL[з.state] || з.state)}</span></td>
        <td><b>${esc(з.label || з.metric)}</b><div class="faint">${esc(з.severity || '')}</div></td>
        <td class="nowrap">${esc(metricValue(з.value, з.unit))}</td>
        <td class="nowrap dim">${знакПорога(з.direction, з.inclusive)} ${esc(metricValue(з.threshold, з.unit))}</td>
      </tr>`).join('')}</tbody></table></div>`
      : '<div class="empty small">С запуска сервера тревоги не срабатывали.</div>';
  },

  /* Графики нагрузки: сервер и каждая видеокарта отдельно.
   *
   * «Средняя загрузка видеокарты» — величина, из которой ничего не следует,
   * поэтому карты никогда не складываются в один ряд, даже когда их две.
   */
  async loadResources(minutes) {
    const host = qs('#mon-charts');
    if (!host) return;
    let data;
    try {
      data = await API.latest('mon-res', `/api/monitoring/resources?minutes=${minutes}`);
    } catch (err) {
      if (!(err && err.silent)) host.innerHTML =
        `<div class="empty">Не удалось получить ряды: ${esc(err.message)}</div>`;
      return;
    }
    const счётчик = qs('#mon-sampled');
    if (счётчик) счётчик.textContent = `замеров: ${num(data.sampled)}`;
    if (!data.sampled) {
      host.innerHTML = '<div class="empty">За это окно замеров ещё нет — сервер их пишет раз в несколько секунд</div>';
      return;
    }

    const s = data.system || {};
    const метки = (s.ts || []).map((t) => new Date(t * 1000).toLocaleTimeString('ru-RU',
      { hour: '2-digit', minute: '2-digit' }));
    const памятьВсего = s.ram_total_mb || 0;

    host.innerHTML = `
      <div class="grid cols-2">
        <div><b class="small">Процессор</b><div id="mon-cpu"></div></div>
        <div><b class="small">Оперативная память${памятьВсего
          ? `, всего ${num(памятьВсего / 1024, 1)} ГБ` : ''}</b><div id="mon-ram"></div></div>
      </div>
      <div class="grid cols-2">
        <div><b class="small">Очередь и работа</b><div id="mon-queue"></div></div>
        <div><b class="small">Свободно на диске</b><div id="mon-disk"></div></div>
      </div>
      ${(data.gpus || []).map((g) => `
        <div class="card tight" style="margin-top:12px">
          <div class="row" style="margin-bottom:8px">
            <b>${esc(g.name)}</b>
            <span class="chip">GPU ${g.gpu}</span>
            ${g.mem_total_mb ? `<span class="chip">${num(g.mem_total_mb / 1024, 1)} ГБ</span>` : ''}
            ${g.power_limit_w ? `<span class="chip">предел ${num(g.power_limit_w, 0)} Вт</span>` : ''}
          </div>
          <div class="grid cols-2">
            <div><b class="small">Загрузка и память</b><div id="mon-gpu-${g.gpu}"></div></div>
            <div><b class="small">Температура и потребление</b>
                 <div id="mon-gpu-t-${g.gpu}"></div></div>
          </div>
        </div>`).join('')
      || '<div class="empty small" style="margin-top:12px">Видеокарты не обнаружены — рядов по ним нет</div>'}`;

    Charts.line(qs('#mon-cpu'), { labels: метки, area: true, unit: ' %', yMax: 100,
      series: [{ name: 'Загрузка', values: s.cpu_percent || [] }] });
    Charts.line(qs('#mon-ram'), { labels: метки, area: true, unit: ' МБ',
      yMax: памятьВсего || undefined,
      series: [{ name: 'Занято', values: s.ram_used_mb || [] }] });
    Charts.line(qs('#mon-queue'), { labels: метки,
      series: [{ name: 'В очереди', values: s.queue_depth || [] },
               { name: 'В работе', values: s.active_jobs || [] }] });
    Charts.line(qs('#mon-disk'), { labels: метки, area: true, unit: ' ГБ',
      series: [{ name: 'Свободно', values: s.disk_free_gb || [] }] });

    (data.gpus || []).forEach((g) => {
      const их = (g.ts || []).map((t) => new Date(t * 1000).toLocaleTimeString('ru-RU',
        { hour: '2-digit', minute: '2-digit' }));
      // Загрузка в процентах и память в мегабайтах — величины разного
      // порядка, поэтому память переводим в проценты от установленной. Так
      // обе линии живут на одной шкале честно, без второй оси.
      const памятьДоля = g.mem_total_mb
        ? (g.mem_used_mb || []).map((v) => v === null ? null : (v / g.mem_total_mb) * 100)
        : null;
      Charts.line(qs(`#mon-gpu-${g.gpu}`), {
        labels: их, unit: ' %', yMax: 100,
        series: [{ name: 'Загрузка', values: g.util_percent || [] },
                 ...(памятьДоля ? [{ name: 'Память занята', values: памятьДоля }] : [])],
      });
      const ряды = [];
      if ((g.temperature_c || []).some((v) => v !== null)) {
        ряды.push({ name: 'Температура, °C', values: g.temperature_c });
      }
      if ((g.power_w || []).some((v) => v !== null)) {
        ряды.push({ name: 'Потребление, Вт', values: g.power_w });
      }
      const узел = qs(`#mon-gpu-t-${g.gpu}`);
      if (ряды.length) {
        Charts.line(узел, { labels: их, series: ряды });
      } else {
        Charts.empty(узел, 'Карта не отдаёт телеметрию по температуре и мощности');
      }
    });
  },

  async loadCatalog() {
    let data;
    try {
      data = await API.latest('mon-catalog', '/api/monitoring/catalog');
    } catch (err) {
      // Молчаливый выход оставлял карточку на строке «Загрузка справочника…»
      // навсегда: ни всплывашки, ни следа в консоли. Соседний загрузчик
      // рядов в такой же ситуации честно пишет, что не вышло.
      const box = qs('#mon-catalog');
      if (box) {
        box.innerHTML = `<div class="empty small">Не удалось получить справочник метрик: ${
          esc((err && err.message) || 'ошибка запроса')}</div>`;
      }
      return;
    }
    state.metricCatalog = data;
    const box = qs('#mon-catalog');
    const search = qs('#mon-search');
    // Ответ мог прийти после ухода из раздела: тогда этих элементов уже нет,
    // и попытка навесить обработчик роняла скрипт целиком («Cannot set
    // properties of null»), а вместе с ним и обновление всех разделов.
    if (!box || !search) return;
    const draw = () => {
      const needle = (search.value || '').toLowerCase().trim();
      const items = data.metrics.filter((m) => !needle
        || m.name.toLowerCase().includes(needle)
        || m.label.toLowerCase().includes(needle)
        || m.description.toLowerCase().includes(needle));
      const counter = qs('#mon-count');
      if (counter) counter.textContent = `${items.length} из ${data.metrics.length}`;
      box.innerHTML = data.groups.map((group) => {
        const inGroup = items.filter((m) => m.group === group.id);
        if (!inGroup.length) return '';
        return `<h4 style="margin:16px 0 8px">${esc(group.title)}
            <span class="small dim" style="font-weight:400">${esc(group.description)}</span></h4>
          ${inGroup.map(metricCard).join('')}`;
      }).join('') || '<div class="empty">Ничего не найдено</div>';
    };
    search.oninput = draw;
    draw();
  },
};

function healthLabel(status) {
  return { ok: 'норма', warning: 'внимание', degraded: 'деградация',
           critical: 'авария', critical_alert: 'критическая тревога' }[status] || status;
}

function probeCard(name, probe) {
  if (!probe) return '';
  const title = { liveness: 'Живость', readiness: 'Готовность',
                  startup: 'Запуск' }[name] || name;
  const cls = probe.status === 'ok' ? 'ok' : probe.status === 'warn' ? 'warn' : 'err';
  return `<div class="card" style="margin:0">
    <div class="card-head"><h3>${title}</h3><span class="spacer"></span>
      <span class="chip ${cls}">${esc(probe.status)}</span></div>
    <table class="small">${(probe.checks || []).map((c) => `<tr>
      <td class="dim">${esc(c.name)}</td>
      <td><span class="chip ${c.status === 'ok' ? 'ok' : c.status === 'warn' ? 'warn' : 'err'}"
          >${esc(c.status)}</span></td>
      <td>${esc(c.detail)}${c.hint ? `<div class="small dim">${esc(c.hint)}</div>` : ''}</td>
    </tr>`).join('')}</table></div>`;
}

/**
 * Значение метрики в человеческих единицах.
 *
 * Каталог хранит метрики в базовых единицах Prometheus — байтах и секундах.
 * Это правильно для сбора, но в таблице тревог получалось «31.6 млрд Б»
 * вместо «29.5 ГБ» и «5400 с» вместо «1:30:00»: разобрать, много это или
 * мало, было нельзя.
 */
function metricValue(value, unit) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return '—';
  const v = Number(value);
  if (unit === 'Б' || unit === 'B') return fmtBytes(v);
  if (unit === 'с' || unit === 's') {
    if (Math.abs(v) < 1) return `${num(v * 1000, 0)} мс`;
    if (Math.abs(v) < 60) return `${num(v, v < 10 ? 2 : 1)} с`;
    return fmtDur(v);
  }
  // Три знака — без хвостовых нулей: «1,000» при запятой читается и как
  // «одна», и как «тысяча», а «0,930» — просто шум.
  const текст = Number.isInteger(v) ? String(v) : num(v, 3).replace(/,?0+$/, '');
  return `${текст}${unit ? ' ' + unit : ''}`;
}

/** Байты в КБ/МБ/ГБ/ТБ по основанию 1024. */
function fmtBytes(value) {
  const v = Number(value);
  if (!Number.isFinite(v)) return '—';
  const sign = v < 0 ? '-' : '';
  let rest = Math.abs(v);
  const units = ['Б', 'КБ', 'МБ', 'ГБ', 'ТБ', 'ПБ'];
  let i = 0;
  while (rest >= 1024 && i < units.length - 1) { rest /= 1024; i += 1; }
  const digits = i === 0 ? 0 : (rest < 10 ? 2 : rest < 100 ? 1 : 0);
  return `${sign}${rest.toFixed(digits).replace('.', ',')} ${units[i]}`;
}

/** Знак порога так же, как его проверяет сервер: включительный — «≥» и «≤». */
function знакПорога(direction, inclusive) {
  if (direction === 'above') return inclusive ? '≥' : '>';
  return inclusive ? '≤' : '<';
}

function alertsTable(alerts) {
  const active = alerts.filter((a) => a.state !== 'ok');
  // Метки — рядом с именем метрики: две тревоги «Доля успеха» по разным
  // моделям выглядели одинаково, и не понять было, какая из моделей сбоит.
  const метки = (a) => Object.entries(a.labels || {})
    .map(([к, з]) => `${esc(к)}=${esc(з)}`).join(', ');
  const rows = (active.length ? active : alerts.slice(0, 12)).map((a) => `<tr>
    <td><span class="chip ${ALERT_STATE_CLASS[a.state] || ''}">${
      esc(ALERT_STATE_LABEL[a.state] || a.state)}</span></td>
    <td><b>${esc(a.label)}</b><div class="small dim">${esc(a.metric)}${
      метки(a) ? ` · ${метки(a)}` : ''}</div></td>
    <td class="nowrap">${esc(metricValue(a.value, a.unit))}</td>
    <td class="dim nowrap">${знакПорога(a.direction, a.inclusive)} ${
      esc(metricValue(a.threshold, a.unit))}</td>
    <td class="small">${esc(a.severity)}</td>
    <td class="small dim">${esc(a.hint || '')}</td></tr>`).join('');
  return `<div class="table-wrap"><table>
    <thead><tr><th>Состояние</th><th>Метрика</th><th>Значение</th><th>Порог</th>
      <th>Важность</th><th>Что делать</th></tr></thead>
    <tbody>${rows || '<tr><td colspan="6" class="empty">Тревог нет</td></tr>'}</tbody>
  </table></div>${active.length ? '' :
    '<p class="small dim" style="margin-top:8px">Показаны первые правила; все они в норме.</p>'}`;
}

function targetsTable(data) {
  // «Доставляется» — только после первой удачной отправки. Свежий приёмник,
  // к которому ещё не ходили, красной плашкой не пугает: судить не о чем.
  const состояние = (t) => {
    if (t.enabled === false) return '<span class="chip idle">выключен</span>';
    if (!t.last_attempt) return '<span class="chip idle">ещё не отправляли</span>';
    return `<span class="chip ${t.healthy ? 'ok' : 'err'}">${t.healthy ? 'доставляется' : 'нет'}</span>`;
  };
  const rows = (data.targets || []).map((t) => `<tr>
    <td><b>${esc(t.name)}</b></td>
    <td>${esc(TARGET_KIND_LABEL[t.kind] || t.kind)}</td>
    <td class="small">${esc(t.url)}</td>
    <td>${t.interval_s} с</td>
    <td>${состояние(t)}
      ${t.last_error ? `<div class="small dim">${esc(t.last_error)}</div>` : ''}
      ${!t.last_error && t.last_info ? `<div class="small faint">${esc(t.last_info)}</div>` : ''}</td>
    <td class="small dim">отправлено ${t.sent}, ошибок ${t.failed}</td>
    <td class="nowrap admin-only"><button class="ghost sm" data-toggle-target="${esc(t.name)}"
      title="${t.enabled === false ? 'Снова отправлять метрики сюда' : 'Перестать отправлять, не удаляя настройку'}">${
        t.enabled === false ? 'Включить' : 'Выключить'}</button>
      <button class="ghost sm" data-drop-target="${esc(t.name)}"
      title="Убрать приёмник — метрики туда больше не пойдут">Убрать</button></td></tr>`).join('');
  return `<div class="table-wrap"><table>
    <thead><tr><th>Имя</th><th>Тип</th><th>Адрес</th><th>Интервал</th>
      <th>Доставка</th><th>Счётчики</th><th></th></tr></thead>
    <tbody>${rows || `<tr><td colspan="7" class="empty">
      Приёмники не настроены — метрики забирает система сбора сама
      </td></tr>`}</tbody></table></div>`;
}

/* Итог сохранения из раздела: записано ли в config.yaml. */
function persistedHint(result) {
  if (!result || result.persisted !== false) return 'Записано в файл конфигурации';
  return `Действует до перезапуска: ${result.reason || 'в файл конфигурации не записано'}`;
}

/* Вид сообщения по итогу сохранения: не записалось в файл — предупреждение. */
function persistedKind(result) {
  return result && result.persisted === false ? 'warn' : 'ok';
}

/* Заголовок сообщения: «сохранено» — только если действительно записано в файл. */
function сохраненоИли(result, сохранено, применено) {
  return result && result.persisted === false ? применено : сохранено;
}

/**
 * Параметры из раздела — применить и записать в файл конфигурации.
 *
 * Разделы со своими параметрами (очередь, копии, очередь модели, скрипт и
 * категории разбора, рекомендации оборудования) слали PUT /api/settings,
 * который действует до перезапуска, и отвечали «Сохранено». Перезапуск —
 * хотя бы обновление — молча возвращал прежние значения. Теперь сервер
 * записывает названные параметры в config.yaml, и только их: то, что на
 * странице настроек применено на пробу, в файл не уходит.
 */
async function сохранитьПараметры(значения) {
  // Сохранения идут по одному, в порядке нажатий: два быстрых изменения
  // одного поля уходили параллельно, сервер применял их в каком придётся
  // порядке, и последним оставалось не последнее.
  const мой = (сохранитьПараметры.хвост || Promise.resolve())
    .catch(() => null)
    .then(() => API.put('/api/settings?persist=true', значения));
  сохранитьПараметры.хвост = мой;
  const итог = await мой;
  Object.assign(state.settings, (итог && итог.applied) || значения);
  return итог;
}

function endpointsTable() {
  const rows = [
    ['/api/monitoring/metrics', 'Все метрики. Формат задаётся ?format=prometheus|openmetrics|json|otlp|influx|graphite|zabbix|zabbix_sender|csv'],
    ['/api/monitoring/metrics.json', 'Снимок с описанием и порогами каждой метрики'],
    ['/api/monitoring/health', 'Сводное состояние: живость, готовность, тревоги'],
    ['/api/monitoring/live', 'Проба живости — провал означает «перезапусти контейнер»'],
    ['/api/monitoring/ready', 'Проба готовности — провал означает «не шли запросы»'],
    ['/api/monitoring/catalog', 'Справочник метрик с рекомендациями'],
    ['/api/monitoring/alerts', 'Состояние тревог'],
  ];
  return `<div class="table-wrap"><table>
    <thead><tr><th>Адрес</th><th>Что отдаёт</th></tr></thead>
    <tbody>${rows.map(([path, what]) => `<tr>
      <td><a href="${path}" data-mon-open="${path}"><code>${path}</code></a></td>
      <td class="small">${esc(what)}</td></tr>`).join('')}</tbody></table></div>`;
}

/**
 * Порог метрики словами — как его проверяет сервер на этой установке.
 *
 * Справочник писал «выше … — предупреждение, … — критично» всегда: у
 * признака «модель доступна» критического уровня нет, и выходило
 * «критично: —»; включительные пороги («не меньше 1») читались строгими.
 */
function описаниеПорога(порог, unit) {
  const слово = порог.direction === 'above'
    ? (порог.inclusive ? 'не меньше' : 'выше')
    : (порог.inclusive ? 'не больше' : 'ниже');
  const уровни = [];
  if (порог.warning !== null && порог.warning !== undefined) {
    уровни.push(`${слово} ${esc(metricValue(порог.warning, unit))} — предупреждение`);
  }
  if (порог.critical !== null && порог.critical !== undefined) {
    уровни.push(`${слово} ${esc(metricValue(порог.critical, unit))} — критично`);
  }
  return `Порог: ${уровни.join(', ') || 'не задан'}; выдержка ${num(порог.for_seconds || 0, 0)} с.
    ${порог.note ? esc(порог.note) : ''}`;
}

function metricCard(m) {
  const threshold = m.threshold;
  return `<details class="help" style="margin-bottom:6px">
    <summary><b>${esc(m.label)}</b> <code class="small">${esc(m.name)}</code>
      <span class="small dim">${esc(m.type)}${m.unit ? ', ' + esc(m.unit) : ''}</span></summary>
    <div class="small" style="padding:8px 0 4px">
      <p>${esc(m.description)}</p>
      ${m.normal ? `<p class="dim">Обычное значение: ${esc(m.normal)}</p>` : ''}
      ${m.recommendation ? `<div class="param-rec"><b>Рекомендация.</b> ${esc(m.recommendation)}</div>` : ''}
      ${threshold ? `<p class="dim">${описаниеПорога(threshold, m.unit)}</p>` : ''}
      ${m.troubleshooting ? `<p><b>Что делать:</b> ${esc(m.troubleshooting)}</p>` : ''}
      ${(m.labels || []).length ? `<p class="dim">Метки: ${m.labels.map(
        (l) => `<code>${esc(l)}</code>`).join(', ')}</p>` : ''}
    </div></details>`;
}

function targetDialog() {
  const backdrop = h(`<div class="modal-backdrop"><div class="modal" style="max-width:560px">
    <div class="modal-head"><b>Новый приёмник метрик</b><span class="spacer"></span>
      <button class="ghost icon" id="tg-close" aria-label="Закрыть" title="Закрыть">✕</button></div>
    <div class="modal-body">
      <label class="mon-field"><span>Тип</span>
        <select id="tg-kind">${Object.entries(TARGET_KIND_LABEL).map(
          ([k, v]) => `<option value="${k}">${esc(v)}</option>`).join('')}</select></label>
      <label class="mon-field"><span>Имя</span>
        <input type="text" id="tg-name" placeholder="по виду приёмника"></label>
      <label class="mon-field"><span>Адрес</span>
        <input type="text" id="tg-url" placeholder="http://pushgw:9091"></label>
      <label class="mon-field" id="tg-host-row" hidden><span>Узел в Zabbix</span>
        <input type="text" id="tg-host" placeholder="имя узла, как оно заведено в Zabbix"></label>
      <label class="mon-field"><span>Интервал, секунд</span>
        <input type="number" id="tg-interval" value="60" min="10"></label>
      <!-- Поля, которые сервер принимает, а интерфейс раньше не давал задать:
           InfluxDB с токеном, Pushgateway со своим job, тайм-аут. Видны те,
           что нужны выбранному виду приёмника. -->
      <label class="mon-field" data-kinds="influxdb"><span>База InfluxDB</span>
        <input type="text" id="tg-database" placeholder="asrhub"></label>
      <label class="mon-field" data-kinds="prometheus_pushgateway"><span>job</span>
        <input type="text" id="tg-job" placeholder="asrhub"></label>
      <label class="mon-field" data-kinds="prometheus_pushgateway"><span>instance</span>
        <input type="text" id="tg-instance" placeholder="имя этой машины"></label>
      <label class="mon-field" data-kinds="statsd"><span>Префикс имён</span>
        <input type="text" id="tg-prefix" placeholder="asrhub"></label>
      <label class="mon-field" data-kinds="prometheus_pushgateway influxdb otlp webhook"><span>Заголовки</span>
        <textarea id="tg-headers" rows="2" class="mono"
          placeholder="Authorization: Token …&#10;по одному на строке"></textarea></label>
      <label class="mon-field"><span>Тайм-аут, секунд</span>
        <input type="number" id="tg-timeout" value="10" min="1" max="120" step="1"></label>
      <p class="small dim">Проверка отправляет текущий снимок немедленно и показывает
        результат — настройку видно до того, как она сохранена. Сохранённый приёмник
        записывается в файл конфигурации и переживает перезапуск; остальные приёмники
        при добавлении не меняются.</p>
      <div id="tg-result" class="small"></div>
    </div>
    <div class="modal-foot">
      <button class="ghost" id="tg-test">Проверить</button>
      <span class="spacer"></span>
      <button class="primary" id="tg-save">Добавить</button>
    </div></div></div>`);
  mountModal(backdrop);
  const close = () => closeModal(backdrop);
  qs('#tg-close', backdrop).onclick = close;

  const вид = qs('#tg-kind', backdrop);
  const обновитьВид = () => {
    qs('#tg-url', backdrop).placeholder = TARGET_URL_HINT[вид.value] || '';
    qs('#tg-host-row', backdrop).hidden = вид.value !== 'zabbix';
    qsa('[data-kinds]', backdrop).forEach((поле) => {
      поле.hidden = !поле.dataset.kinds.split(' ').includes(вид.value);
    });
  };
  вид.addEventListener('change', обновитьВид);
  обновитьВид();

  const collect = () => {
    const описание = {
      kind: вид.value,
      url: qs('#tg-url', backdrop).value.trim(),
      interval_s: Number(qs('#tg-interval', backdrop).value) || 60,
    };
    const имя = qs('#tg-name', backdrop).value.trim();
    if (имя) описание.name = имя;
    const узел = qs('#tg-host', backdrop).value.trim();
    if (вид.value === 'zabbix' && узел) описание.host = узел;
    // Только видимые для этого вида поля и только заполненные: пустое —
    // умолчание сервера.
    const поле = (ид, ключ) => {
      const п = qs(ид, backdrop);
      if (п && !п.closest('[hidden]') && п.value.trim()) описание[ключ] = п.value.trim();
    };
    поле('#tg-database', 'database');
    поле('#tg-job', 'job');
    поле('#tg-instance', 'instance');
    поле('#tg-prefix', 'prefix');
    const тайм = Number(qs('#tg-timeout', backdrop).value);
    if (тайм > 0) описание.timeout_s = тайм;
    const заголовки = qs('#tg-headers', backdrop);
    if (заголовки && !заголовки.closest('[hidden]')) {
      const набор = {};
      заголовки.value.split('\n').forEach((строка) => {
        const i = строка.indexOf(':');
        if (i > 0) набор[строка.slice(0, i).trim()] = строка.slice(i + 1).trim();
      });
      if (Object.keys(набор).length) описание.headers = набор;
    }
    return описание;
  };

  qs('#tg-test', backdrop).onclick = async () => {
    const box = qs('#tg-result', backdrop);
    box.innerHTML = 'Отправка…';
    try {
      const result = await API.post('/api/monitoring/targets/test', collect());
      box.innerHTML = result.ok
        ? `<span class="chip ok">доставлено</span> метрик: ${result.sent_metrics}${
          result.info ? ` <span class="dim">· ${esc(result.info)}</span>` : ''}`
        : `<span class="chip err">не доставлено</span> ${esc(result.error || '')}`;
    } catch (err) {
      box.innerHTML = `<span class="chip err">ошибка</span> ${esc(err.message || '')}`;
    }
  };

  // Добавляется один приёмник, а не список целиком. Прежде список
  // собирался из ответа GET, где не было заголовков, базы и признака
  // «выключен», и сохранение стирало всё это у прежних приёмников.
  qs('#tg-save', backdrop).onclick = (e) => занятьКнопку(e.currentTarget, async () => {
    const описание = collect();
    if (!описание.url) {
      toast('Укажите адрес приёмника', 'err', TARGET_URL_HINT[описание.kind] || '');
      return;
    }
    try {
      const итог = await API.post('/api/monitoring/targets', описание);
      toast(`Приёмник «${(итог.target || {}).name || описание.kind}» добавлен`,
            итог.persisted === false ? 'warn' : 'ok', persistedHint(итог));
      close();
      renderView();
    } catch (err) { fail(err); }
  });
}

RENDERERS.logs = {
  render(root) {
    root.innerHTML = `
      <div class="settings-toolbar">
        <select id="log-level" style="width:150px">
          <option value="">Все уровни</option>
          <option value="INFO">INFO и выше</option>
          <option value="WARNING">WARNING и выше</option>
          <option value="ERROR">Только ошибки</option>
        </select>
        <input type="search" id="log-search" placeholder="поиск по журналу" style="width:280px">
        <label class="row" style="gap:6px;cursor:pointer">
          <input type="checkbox" id="log-auto" checked style="width:auto">
          <span class="small">обновлять автоматически</span></label>
        <span class="spacer"></span>
        <span class="small faint" id="log-counts"></span>
      </div>
      <div class="grid cols-2">
        ${card('Журнал сервера', '', '<div class="table-wrap" id="log-table"></div>')}
        ${card('События заданий', '', '<div class="table-wrap" id="event-table"></div>')}
      </div>`;
    qs('#log-level').onchange = () => this.load();
    let timer;
    qs('#log-search').oninput = () => { clearTimeout(timer); timer = setTimeout(() => this.load(), 300); };
    this.load();
    // Таймер регистрируется за разделом: при уходе он гасится сам, иначе при
    // каждом возврате добавлялся ещё один опрос.
    viewTimer(() => {
      if (qs('#log-auto') && qs('#log-auto').checked) this.load();
    }, 5000);
  },

  async load() {
    try {
      const level = qs('#log-level') ? qs('#log-level').value : '';
      const search = qs('#log-search') ? qs('#log-search').value : '';
      // allSettled, а не all: журнал сервера открыт только администратору,
      // и его 403 отменял загрузку целиком — обычный пользователь видел
      // пустую панель событий вместо своих, и так каждые пять секунд.
      const [logsResult, eventsResult] = await Promise.allSettled([
        API.latest('logs', `/api/logs?limit=250&level=${level}&search=${encodeURIComponent(search)}`),
        API.latest('log-events', '/api/events?limit=150'),
      ]);
      // Отменённый запрос — не отказ: его сменил более свежий, и рисовать
      // по нему «нет прав» нельзя. Про права — только на настоящий 403;
      // прочие сбои называются своим текстом. Раньше любой сбой журнала,
      // даже отмена при быстрой смене уровня, писал администратору «доступен
      // только администратору», а сбой событий выглядел как «Событий нет».
      const отменён = (р) => р.status === 'rejected' && р.reason && р.reason.silent;
      if (отменён(logsResult) || отменён(eventsResult)) return;
      const logsFailed = logsResult.status === 'rejected';
      const logsDenied = logsFailed && logsResult.reason && logsResult.reason.status === 403;
      const logs = logsFailed ? { items: [], counts: {} } : logsResult.value;
      const eventsFailed = eventsResult.status === 'rejected';
      const events = eventsFailed ? { items: [] } : eventsResult.value;
      const counts = qs('#log-counts');
      if (counts) {
        counts.innerHTML = Object.entries(logs.counts || {})
          .map(([k, v]) => `<span class="chip ${k === 'ERROR' ? 'err'
            : k === 'WARNING' ? 'warn' : ''}">${k}: ${v}</span>`).join(' ');
      }
      const table = qs('#log-table');
      if (table && logsDenied) {
        table.innerHTML = '<div class="empty">Журнал сервера доступен только ключу '
          + 'с ролью администратора.</div>';
      } else if (table && logsFailed) {
        table.innerHTML = `<div class="empty">Журнал не получен: ${
          esc((logsResult.reason && logsResult.reason.message) || 'ошибка запроса')}</div>`;
      } else if (table) {
        table.innerHTML = logs.items.length ? `<table>
          <thead><tr><th style="width:70px">Время</th><th style="width:80px">Уровень</th>
            <th>Сообщение</th></tr></thead><tbody>
          ${logs.items.slice().reverse().map((l) => `<tr>
            <td class="small faint mono nowrap">${esc(l.time.split(' ')[1] || l.time)}</td>
            <td><span class="chip ${l.level === 'ERROR' ? 'err'
              : l.level === 'WARNING' ? 'warn' : ''}">${esc(l.level)}</span></td>
            <td class="small"><span class="faint mono">${esc(l.logger.replace('asrhub.', ''))}</span>
              ${esc(l.message)}
              ${l.job_id ? `<span class="chip" style="margin-left:6px">${
                esc(String(l.job_id).slice(0, 12))}</span>` : ''}</td>
          </tr>`).join('')}</tbody></table>` : '<div class="empty small">Записей нет</div>';
      }
      const eventTable = qs('#event-table');
      if (eventTable && eventsFailed) {
        eventTable.innerHTML = `<div class="empty small">События не получены: ${
          esc((eventsResult.reason && eventsResult.reason.message) || 'ошибка запроса')}</div>`;
      } else if (eventTable) {
        eventTable.innerHTML = events.items.length ? `<table>
          <thead><tr><th style="width:110px">Время</th><th style="width:120px">Событие</th>
            <th>Описание</th></tr></thead><tbody>
          ${events.items.map((e) => `<tr>
            <td class="small faint nowrap">${fmtTime(e.ts)}</td>
            <td><span class="chip">${esc(e.kind)}</span></td>
            <td class="small">${esc(e.message || '')}
              ${e.job_id ? `<button class="ghost sm"
                onclick="__asrhub.openJob(${jsArg(e.job_id)})">задание</button>` : ''}</td>
          </tr>`).join('')}</tbody></table>` : '<div class="empty small">Событий нет</div>';
      }
    } catch (err) {
      // Молча пустой журнал выглядит как «ошибок нет», хотя на деле мы просто
      // не смогли их получить. Показываем причину.
      const table = qs('#log-table');
      if (table) {
        table.innerHTML = `<div class="empty small">Журнал недоступен: ${
          esc(String(err.message || err))}</div>`;
      }
    }
  },
};

